//! LocalDb parity harness (Todo 14).
//!
//! Runs the real [`LocalDbDriver`] against the seed database generated by
//! `scripts/qa/gen_parity_fixture.py` from `assets/app/db/apps.db`, then writes
//! the same JSON document the Dart harness produces from the real Floor DAO and
//! `LocalDbChannel`.  Run through `scripts/qa/parity.sh --channel`; the script
//! rebuilds the seed every run and is the gate.
//!
//! The driver is opened through [`DbHandle::open_at`] so the Rust-side schema
//! (`apps`, `categories`, `app_config`, `apps_fts`) is applied exactly as the
//! production core does.  Input queries are shared constants with the Dart
//! harness in `test/parity/dump_dart_parity_test.dart`.

use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use serde_json::{json, Value};

use gstore_core::channel::{ChannelDriver, LocalDbDriver};
use gstore_core::db::DbHandle;
use gstore_core::dto::{
    AppDetail, AppSummary, ChannelKey, ChannelKind, ChannelMeta, DetailSection,
};
use gstore_core::error::Error;

const SEARCH_QUERY: &str = "clash";
const APP_ID: &str = "com.artemchep.keyguard";
const MISSING_APP_ID: &str = "com.example.missing";
const KNOWN_CATEGORY: &str = "PROXY";
const UNKNOWN_CATEGORY: &str = "NO_SUCH_CATEGORY";

struct Args {
    db: PathBuf,
    out: PathBuf,
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("gstore_core_parity: {err}");
            ExitCode::FAILURE
        }
    }
}

fn run() -> Result<(), String> {
    let args = parse_args()?;
    if !args.db.is_file() {
        return Err(format!("seed database not found: {}", args.db.display()));
    }

    let handle = DbHandle::open_at(&args.db)
        .map_err(|e| format!("open seeded db {}: {e}", args.db.display()))?;
    let driver = LocalDbDriver::new(channel_key()?, channel_meta(), handle);

    let all = driver
        .get_all_apps(false)
        .map_err(|e| format!("getAllApps: {e}"))?;
    let search = driver
        .search_apps(SEARCH_QUERY, false)
        .map_err(|e| format!("searchApps({SEARCH_QUERY}): {e}"))?;
    let search_empty = driver
        .search_apps("", false)
        .map_err(|e| format!("searchApps(\"\"): {e}"))?;
    let by_category = driver
        .search_by_category(KNOWN_CATEGORY, false)
        .map_err(|e| format!("searchByCategory({KNOWN_CATEGORY}): {e}"))?;
    let by_unknown_category = driver
        .search_by_category(UNKNOWN_CATEGORY, false)
        .map_err(|e| format!("searchByCategory({UNKNOWN_CATEGORY}): {e}"))?;

    let info = info_json(&driver, APP_ID)?;
    let info_missing = info_json(&driver, MISSING_APP_ID)?;
    let detail = detail_json(&driver, APP_ID)?;
    let detail_missing = detail_json(&driver, MISSING_APP_ID)?;

    let document = json!({
        "queries": {
            "search": SEARCH_QUERY,
            "appId": APP_ID,
            "missingAppId": MISSING_APP_ID,
            "knownCategory": KNOWN_CATEGORY,
            "unknownCategory": UNKNOWN_CATEGORY,
        },
        "getAllApps": all.iter().map(summary_json).collect::<Vec<_>>(),
        "searchApps": search.iter().map(summary_json).collect::<Vec<_>>(),
        "searchEmpty": search_empty.iter().map(summary_json).collect::<Vec<_>>(),
        "searchByCategory": {
            KNOWN_CATEGORY: by_category.iter().map(summary_json).collect::<Vec<_>>(),
            UNKNOWN_CATEGORY: by_unknown_category.iter().map(summary_json).collect::<Vec<_>>(),
        },
        "getAppInfo": info,
        "getAppInfoMissing": info_missing,
        "getAppDetail": detail,
        "getAppDetailMissing": detail_missing,
    });

    if let Some(parent) = args.out.parent() {
        fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    let bytes =
        serde_json::to_vec_pretty(&document).map_err(|e| format!("serialize parity json: {e}"))?;
    fs::write(&args.out, bytes).map_err(|e| format!("write {}: {e}", args.out.display()))?;
    Ok(())
}

fn channel_key() -> Result<ChannelKey, String> {
    ChannelKey::new("local_db").map_err(|e| format!("invalid parity channel key local_db: {e}"))
}

fn channel_meta() -> ChannelMeta {
    ChannelMeta {
        kind: ChannelKind::LocalDb,
        name: "LocalDB".to_string(),
        description: "LocalDb parity channel".to_string(),
        enabled: true,
        priority: 10,
        support_offline: true,
        last_update_time: None,
        version: Some("1".to_string()),
    }
}

fn info_json(driver: &LocalDbDriver, app_id: &str) -> Result<Value, String> {
    match driver.get_app_info(app_id, false) {
        Ok(app) => Ok(summary_json(&app)),
        Err(Error::NotFound(_)) => Ok(Value::Null),
        Err(error) => Err(format!("getAppInfo({app_id}): {error}")),
    }
}

fn detail_json(driver: &LocalDbDriver, app_id: &str) -> Result<Value, String> {
    match driver.get_app_detail(app_id, false) {
        Ok(detail) => Ok(app_detail_json(driver, &detail)),
        Err(Error::NotFound(_)) => Ok(Value::Null),
        Err(error) => Err(format!("getAppDetail({app_id}): {error}")),
    }
}

fn summary_json(app: &AppSummary) -> Value {
    json!({
        "appId": app.app_id,
        "packageName": app.package_name,
        "name": app.name,
        "user": app.user,
        "repositories": app.repositories,
        "icon": app.icon,
        "des": app.des,
        "readme": app.readme,
        "category": app.category,
        "extra": app.extra,
    })
}

/// Shared detail projection with the Dart harness.
///
/// Dart's `LocalDbChannelDetailProxy.extra` is a UI render payload (proxy,
/// repository name, apiData) with no corresponding SQLite column; both harnesses
/// compare the fields that come from the database plus the same readme/section
/// fallback (`fetchReadme` returns the README column, else `des`).
fn app_detail_json(driver: &LocalDbDriver, detail: &AppDetail) -> Value {
    let readme = driver.fetch_readme(&detail.app_id).ok().flatten();
    json!({
        "appId": detail.app_id,
        "name": detail.name,
        "icon": detail.icon,
        "description": detail.description,
        "version": detail.version,
        "developer": detail.developer,
        "packageName": detail.package_name,
        "projectUrl": detail.project_url,
        "sections": detail.sections.iter().map(section_code).collect::<Vec<_>>(),
        "downloads": detail.downloads,
        "readme": readme,
    })
}

fn section_code(section: &DetailSection) -> &'static str {
    match section {
        DetailSection::Version => "version",
        DetailSection::Statistics => "statistics",
        DetailSection::Screenshots => "screenshots",
        DetailSection::Readme => "readme",
        DetailSection::Downloads => "downloads",
        DetailSection::Rating => "rating",
        DetailSection::Developer => "developer",
        DetailSection::Changelog => "changelog",
        DetailSection::Permissions => "permissions",
    }
}

fn parse_args() -> Result<Args, String> {
    let mut db = None;
    let mut out = None;
    let mut iter = env::args().skip(1);
    while let Some(arg) = iter.next() {
        match arg.as_str() {
            "--db" => db = Some(iter.next().ok_or("--db requires a path")?),
            "--out" => out = Some(iter.next().ok_or("--out requires a path")?),
            "--help" | "-h" => {
                return Err("usage: gstore_core_parity --db <path> --out <path>".to_string())
            }
            other => return Err(format!("unknown argument: {other}")),
        }
    }
    Ok(Args {
        db: Path::new(&db.ok_or("missing --db <path>")?).to_path_buf(),
        out: Path::new(&out.ok_or("missing --out <path>")?).to_path_buf(),
    })
}
